// Validate & normalize one website-form submission.
// Mode: Run once for all items (a webhook call carries exactly one submission).
//
// Accepts JSON or form-encoded bodies with these fields (aliases in brackets):
//   name [full_name, fullName], email, company [organization], website, phone,
//   message [details, msg], budget, timeline, source [utm_source], page_url,
//   _gotcha  (honeypot: must stay empty - bots tend to fill every field)
//
// Output: { ok, httpStatus, responseBody, errors[], lead }

const req = $('Website form webhook').first().json;

let body = req.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};

const pick = (...keys) => {
  for (const k of keys) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
};

// Strip tags/control chars, collapse whitespace, cap length.
const clean = (v, max) => {
  let s = String(v ?? '')
    .replace(/<[^>]*>/g, ' ')
    // eslint-disable-next-line no-control-regex
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (s.length > max) s = s.slice(0, max).trimEnd() + '…';
  return s;
};

const FREE_MAIL = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'live.com',
  'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.de',
  'yandex.com', 'mail.com', 'zoho.com',
]);
const DISPOSABLE = new Set([
  'mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'temp-mail.org',
  'yopmail.com', 'trashmail.com', 'sharklasers.com', 'getnada.com', 'dispostable.com',
  'maildrop.cc', 'throwawaymail.com',
]);

// Honeypot: pretend success so bots learn nothing, but do not process.
if (String(body._gotcha ?? '').trim() !== '') {
  return [{
    json: {
      ok: false,
      spam: true,
      httpStatus: 200,
      errors: ['honeypot_filled'],
      responseBody: { status: 'received' },
    },
  }];
}

const name = clean(pick('name', 'full_name', 'fullName'), 120);
const email = clean(pick('email', 'Email'), 254).toLowerCase();
const message = clean(pick('message', 'details', 'msg'), 4000);
const errors = [];

const EMAIL_RE = /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/;
const emailDomain = email.includes('@') ? email.split('@').pop() : '';

if (name.length < 2) errors.push('name: required (min. 2 characters)');
if (!EMAIL_RE.test(email)) errors.push('email: a valid email address is required');
else if (DISPOSABLE.has(emailDomain)) errors.push('email: please use a permanent email address');
if (message.length < 10) errors.push('message: please describe your request (min. 10 characters)');

if (errors.length) {
  return [{
    json: {
      ok: false,
      spam: false,
      httpStatus: 422,
      errors,
      responseBody: { status: 'rejected', errors },
    },
  }];
}

let website = clean(pick('website', 'url'), 200);
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
let websiteDomain = '';
try { websiteDomain = website ? new URL(website).hostname.replace(/^www\./, '') : ''; } catch { website = ''; }

const company = clean(pick('company', 'organization', 'organisation'), 160);
const phoneRaw = clean(pick('phone', 'tel'), 40);
const phone = phoneRaw.replace(/[^\d+]/g, '').replace(/(?!^)\+/g, '');

const leadId = 'lead_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);

const lead = {
  lead_id: leadId,
  received_at: new Date().toISOString(),
  name,
  email,
  email_domain: emailDomain,
  free_email: FREE_MAIL.has(emailDomain),
  company,
  website,
  website_domain: websiteDomain,
  phone: phone.length >= 7 ? phone : '',
  message,
  budget_stated: clean(pick('budget'), 120),
  timeline_stated: clean(pick('timeline'), 120),
  source: clean(pick('source', 'utm_source'), 80) || 'website',
  page_url: clean(pick('page_url', 'pageUrl'), 300),
};

// The subset of fields the LLM is allowed to see (no internal ids/metadata).
const llmInput = {
  name: lead.name,
  email: lead.email,
  email_is_free_provider: lead.free_email,
  company: lead.company || null,
  website: lead.website || null,
  message: lead.message,
  budget: lead.budget_stated || null,
  timeline: lead.timeline_stated || null,
  source: lead.source,
};

return [{
  json: { ok: true, spam: false, httpStatus: 200, errors: [], lead, llm_input: llmInput },
}];

// Dedupe leads by email within a rolling window (LEAD_DEDUPE_WINDOW_HOURS).
// Mode: Run once for all items.
//
// Uses n8n workflow static data, which is persisted for production
// (webhook-triggered) executions only - manual test runs never mark leads as seen.
// The registry is capped and pruned so it cannot grow without bound.

const cfg = $('Config').first().json;
const item = $input.first().json;
const lead = item.lead;

const store = $getWorkflowStaticData('global');
store.leadsSeen = store.leadsSeen || {};

const now = Date.now();
const windowMs = Math.max(0, Number(cfg.dedupeWindowHours) || 0) * 3600 * 1000;

// Prune expired entries and keep at most 5,000 most recent.
for (const [key, ts] of Object.entries(store.leadsSeen)) {
  if (now - ts > windowMs) delete store.leadsSeen[key];
}
const keys = Object.keys(store.leadsSeen);
if (keys.length > 5000) {
  keys.sort((a, b) => store.leadsSeen[a] - store.leadsSeen[b])
    .slice(0, keys.length - 5000)
    .forEach((k) => delete store.leadsSeen[k]);
}

const key = lead.email;
const previous = store.leadsSeen[key];
const duplicate = windowMs > 0 && previous !== undefined;
if (!duplicate) store.leadsSeen[key] = now;

return [{
  json: {
    ...item,
    duplicate,
    previous_submission_at: duplicate ? new Date(previous).toISOString() : null,
  },
}];

// Guardrail: parse and strictly validate the LLM's qualification JSON.
// Mode: Run once for all items.
// Input: Basic LLM Chain output ({ text }) or its error output ({ error }).
// Output: { aiValid, aiErrors[], ai, attempt, rawText }

const ATTEMPT = 1;

const INTENTS = ['purchase', 'quote_request', 'consultation', 'partnership', 'support', 'vendor_pitch', 'job_application', 'spam', 'other'];
const BUDGET_BANDS = ['unknown', '<1k', '1k-5k', '5k-20k', '20k-50k', '50k+'];
const URGENCY = ['low', 'medium', 'high'];

// --- included from src/code/shared/read-llm-json.js ---------------------------
// The Basic LLM Chain returns one of three shapes, depending on model setup:
//   { text: "<raw model output>" }      (string output, e.g. with a fallback model)
//   { ...parsedJsonObject }             (JSON mode: n8n already parsed it)
//   { ...inputFields, error: "..." }    (error output of the chain node - it keeps
//                                        the input item's fields and adds "error")
// Returns { data, raw, error } where data is a plain object or null.
function readLlmJson(input) {
  if (input && input.error) {
    const e = input.error;
    return { data: null, raw: '', error: 'LLM request failed: ' + String((e && e.message) || e).slice(0, 300) };
  }
  let raw;
  let data = null;
  if (input && typeof input.text === 'string' && Object.keys(input).length === 1) {
    raw = input.text;
    const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    try { data = JSON.parse(cleaned); } catch {
      const m = cleaned.match(/\{[\s\S]*\}/);
      if (m) { try { data = JSON.parse(m[0]); } catch { /* not JSON */ } }
    }
  } else {
    data = input;
    raw = JSON.stringify(input);
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return { data: null, raw: String(raw || ''), error: 'Output is not a single JSON object' };
  }
  return { data, raw: String(raw), error: null };
}
// --- end include ----------------------------------------------------------------

const input = $input.first().json;
const errors = [];
const parsed = readLlmJson(input);
const raw = parsed.raw;
const data = parsed.data;
if (parsed.error) errors.push(parsed.error);

const norm = (v) => String(v ?? '').trim().toLowerCase().replace(/[\s-]+/g, '_');
const ai = {};

if (data) {
  // company
  ai.company = typeof data.company === 'string' && data.company.trim() ? data.company.trim().slice(0, 160) : '';
  if (!ai.company) errors.push('company: must be a non-empty string (use "Unknown" if not inferable)');

  // intent
  ai.intent = norm(data.intent);
  if (!INTENTS.includes(ai.intent)) errors.push(`intent: must be one of ${INTENTS.join(', ')} (got "${data.intent}")`);

  // budget band (accept a few harmless spelling variants)
  const b = String(data.budget_band ?? '').trim().toLowerCase().replace(/\s/g, '').replace(/usd|\$/g, '');
  const bandAliases = { 'under1k': '<1k', 'lessthan1k': '<1k', '50k+': '50k+', 'over50k': '50k+', '>50k': '50k+' };
  ai.budget_band = bandAliases[b] || b;
  if (!BUDGET_BANDS.includes(ai.budget_band)) errors.push(`budget_band: must be one of ${BUDGET_BANDS.join(', ')} (got "${data.budget_band}")`);

  // urgency
  ai.urgency = norm(data.urgency);
  if (!URGENCY.includes(ai.urgency)) errors.push(`urgency: must be one of ${URGENCY.join(', ')} (got "${data.urgency}")`);

  // score
  const score = typeof data.score === 'string' && data.score.trim() !== '' ? Number(data.score) : data.score;
  if (typeof score !== 'number' || !Number.isFinite(score) || score < 0 || score > 100) {
    errors.push(`score: must be a number between 0 and 100 (got ${JSON.stringify(data.score)})`);
  } else {
    ai.score = Math.round(score);
  }

  // reasoning
  ai.reasoning = typeof data.reasoning === 'string' ? data.reasoning.trim().slice(0, 800) : '';
  if (ai.reasoning.length < 10) errors.push('reasoning: must explain the score in 1-3 sentences');

  // suggested reply
  ai.suggested_reply = typeof data.suggested_reply === 'string' ? data.suggested_reply.trim() : '';
  if (ai.suggested_reply.length < 40) errors.push('suggested_reply: must be a complete short email body (min. 40 characters)');
  if (ai.suggested_reply.length > 2500) errors.push('suggested_reply: too long (max. 2500 characters)');

  // semantic consistency
  if (ai.intent === 'spam' && ai.score > 20) errors.push('score: spam leads must score 20 or lower');
}

const aiValid = errors.length === 0;

return [{
  json: {
    aiValid,
    aiErrors: errors,
    ai: aiValid ? ai : null,
    attempt: ATTEMPT,
    rawText: raw.slice(0, 2000),
  },
}];

