  json: {
    aiValid,
    aiErrors: errors,
    ai: aiValid ? ai : null,
    attempt: ATTEMPT,
    rawText: raw.slice(0, 2000),
  },
}];

// Both AI attempts failed (invalid output or API error).
// Never lose a lead: continue with status "needs_manual_review".
// Mode: Run once for all items.

const prev = $input.first().json;
let reason = 'Unknown AI failure';
if (Array.isArray(prev.aiErrors) && prev.aiErrors.length) reason = prev.aiErrors.join('; ');
else if (prev.error) reason = 'LLM request failed: ' + (prev.error.message || String(prev.error));

return [{
  json: {
    aiValid: false,
    aiErrors: [reason.slice(0, 500)],
    ai: null,
    attempt: 2,
    fallback: true,
  },
}];

// Combine the normalized lead with the AI qualification into one flat record.
// The record is what gets written to Google Sheets (columns are matched by
// header name; extra fields such as slack_text are ignored by the Sheets node).
// Mode: Run once for all items.

const cfg = $('Config').first().json;
const { lead } = $('Dedupe (72h window)').first().json;
const result = $input.first().json;
const ai = result.aiValid ? result.ai : null;

const threshold = Number(cfg.hotScoreThreshold) || 70;
let tier = 'review';
if (ai) {
  if (ai.intent === 'spam') tier = 'spam';
  else if (ai.score >= threshold) tier = 'hot';
  else if (ai.score >= 40) tier = 'warm';
  else tier = 'cold';
}

// Escape user-controlled text for Slack mrkdwn (prevents <!channel> pings, fake links).
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const quote = (s, max = 500) => {
  const t = String(s ?? '');
  return esc(t.length > max ? t.slice(0, max) + '…' : t).split('\n').map((l) => '> ' + l).join('\n');
};

const company = (ai && ai.company && ai.company !== 'Unknown' ? ai.company : '') || lead.company || 'Unknown company';

const slackHot = [
  `:fire: *Hot lead - score ${ai?.score}/100* (${ai?.urgency} urgency)`,
  `*${esc(lead.name)}* · ${esc(lead.email)} · ${esc(company)}`,
  `*Intent:* ${ai?.intent} · *Budget:* ${ai?.budget_band}${lead.phone ? ' · *Phone:* ' + esc(lead.phone) : ''}`,
  quote(lead.message),
  `*Why:* ${esc(ai?.reasoning)}`,
  `A personalised reply draft is waiting in Gmail drafts. Lead id: \`${lead.lead_id}\``,
].join('\n');

const slackReview = [
  `:warning: *Lead needs manual review* - the AI could not produce a valid qualification.`,
  `*${esc(lead.name)}* · ${esc(lead.email)} · ${esc(lead.company || 'company not given')}`,
  quote(lead.message),
  `*Reason:* ${esc((result.aiErrors || []).join('; ').slice(0, 400))}`,
  `Lead id: \`${lead.lead_id}\``,
].join('\n');

return [{
  json: {
    lead_id: lead.lead_id,
    received_at: lead.received_at,
    status: ai ? 'qualified' : 'needs_manual_review',
    tier,
    score: ai ? ai.score : '',
    intent: ai ? ai.intent : '',
    budget_band: ai ? ai.budget_band : '',
    urgency: ai ? ai.urgency : '',
    company,
    name: lead.name,
    email: lead.email,
    phone: lead.phone,
    website: lead.website,
    message: lead.message,
    budget_stated: lead.budget_stated,
    timeline_stated: lead.timeline_stated,
    source: lead.source,
    reasoning: ai ? ai.reasoning : '',
    suggested_reply: ai ? ai.suggested_reply : '',
    ai_attempts: result.attempt,
    ai_errors: (result.aiErrors || []).join('; '),
    dry_run: Boolean(cfg.dryRun),
    // Not Sheets columns - used by the notification nodes:
    slack_text: tier === 'hot' ? slackHot : slackReview,
    email_subject: `Re: your enquiry${company !== 'Unknown company' ? ' - ' + company : ''}`,
  },
}];

// Build the HTTP response for the website form.
// By default the caller only gets an acknowledgement + lead id. The AI
// qualification is internal sales data and is only included when
// LEAD_RESPONSE_DETAILS=true (useful for testing / server-to-server calls).
// Mode: Run once for all items.

const cfg = $('Config').first().json;
const rec = $('Build lead record').first().json;

const ran = (name) => {
  try { return $(name).isExecuted; } catch { return false; }
};
const actions = [];
if (ran('Log lead to Google Sheets')) actions.push('google_sheets_row');
if (ran('Slack: hot lead alert')) actions.push('slack_hot_lead_alert');
if (ran('Gmail: create reply draft')) actions.push('gmail_reply_draft');
if (ran('Slack: manual review alert')) actions.push('slack_manual_review_alert');

const body = {
  status: 'received',
  lead_id: rec.lead_id,
  message: 'Thanks! We received your request and will get back to you shortly.',
};

if (cfg.responseDetails) {
  body.details = {
    qualification_status: rec.status,
    tier: rec.tier,
    score: rec.score === '' ? null : rec.score,
    intent: rec.intent || null,
    budget_band: rec.budget_band || null,
    urgency: rec.urgency || null,
    company: rec.company,
    reasoning: rec.reasoning || null,
    suggested_reply: rec.suggested_reply || null,
    ai_attempts: rec.ai_attempts,
    ai_errors: rec.ai_errors || null,
    dry_run: rec.dry_run,
    actions,
  };
}

return [{ json: { statusCode: 200, body } }];
